/* AMap uses GCJ-02 coordinates; public landmark positions are approximate, not operating branches. */
let regionalConfig={amapKey:'',amapServiceHost:'',authEnabled:false};
let amapPromise=null,placeQueryTimer=null,placeQueryRevision=0,searchMap=null,pickerMap=null;
function placeById(id){return PLACES.find(p=>p.id===id)||state.remotePlaces?.find(p=>p.id===id)||(state.currentGeo?.id===id?state.currentGeo:null)}
function placeLabel(p){return state.lang==='en'?(p.en||p.name):p.name}
function dateLabel(value){if(!value)return '';return value.replace('T',' ')}
function bookingPlaceOptions(value){return (PLACES.some(p=>p.name===value)?[]:[{name:value}]).concat(PLACES).map(p=>`<option value="${esc(p.name)}" ${p.name===value?'selected':''}>${esc(p.en&&state.lang==='en'?p.en:p.name)}</option>`).join('')}
function dateRangeLabel(b){const format=value=>new Intl.DateTimeFormat(state.lang==='en'?'en-GB':'zh-CN',{month:'short',day:'numeric'}).format(new Date(value.slice(0,10)+'T12:00:00'));return format(b.start)+' — '+format(b.end)}
function adjustReturnDate(){const start=q('start'),end=q('end');end.min=start.value;if(end.value<start.value){let next=new Date(start.value+'T12:00:00');next.setDate(next.getDate()+1);end.value=`${next.getFullYear()}-${String(next.getMonth()+1).padStart(2,'0')}-${String(next.getDate()).padStart(2,'0')}`}}
function regionalLocationOptions(query=''){
 const term=query.trim().toLowerCase();
 const matches=PLACES.filter(p=>!term||`${p.name} ${p.en} ${p.detail} ${p.keywords}`.toLowerCase().includes(term));
 const item=p=>`<button type="button" role="option" class="location-option" onclick="chooseLocation('${esc(p.id)}')"><span class="location-symbol">⌖</span><span><strong ${p.en?'':'data-i18n-preserve'}>${esc(placeLabel(p))}</strong><small ${p.en?'':'data-i18n-preserve'}>${esc(p.detail)}</small></span></button>`;
 let html=`<button type="button" class="location-current" onclick="useCurrentLocation()"><span class="location-symbol">◎</span><span><strong>高德定位 · 使用当前位置</strong><small>${regionalConfig.amapKey?'定位后推荐附近地点':'主要地点可直接选择；高德定位待配置'}</small></span></button><button type="button" class="location-current" onclick="openLocationMap()"><span class="location-symbol">▧</span><span><strong>在地图中选择地点</strong><small>成都主要地点 · 不会直接跳转</small></span></button>`;
 if(state.currentGeo)html+='<h4>高德获取的当前位置</h4>'+item(state.currentGeo);
 if(!term){for(const group of ['机场','交通枢纽','热门地点'])html+=`<h4>${group}</h4>`+matches.filter(p=>p.area===group).map(item).join('')}
 else{html+=`<h4>选择具体地点 · ${matches.length} 个结果</h4>`+matches.map(item).join('');const remote=state.remotePlaces||[];if(remote.length)html+='<h4>高德搜索结果</h4>'+remote.map(item).join('');if(!matches.length&&!remote.length)html+='<div class="location-empty">试试“天府机场”“春熙路”或“成都东站”。</div>';if(regionalConfig.amapKey)html+='<small class="muted">高德搜索限定成都市，部分地点保留当地名称。</small>'}
 return html+'<div class="location-empty">地点为取车位置示意，不代表已运营门店。</div>';
}
function regionalChooseLocation(id){const p=placeById(id);if(!p)return;state.selectedLocationId=id;q('pickup').value=placeLabel(p);localStorage.setItem('yichen-recent-location',id);hideLocations();toast(t('已选择：')+placeLabel(p))}
function regionalLocationTyped(value){state.selectedLocationId=null;state.remotePlaces=[];const revision=++placeQueryRevision;clearTimeout(placeQueryTimer);const panel=q('location-panel');if(panel){panel.hidden=false;panel.innerHTML=localizeHTML(regionalLocationOptions(value))}q('pickup')?.setAttribute('aria-expanded','true');if(!regionalConfig.amapKey||!value.trim())return;placeQueryTimer=setTimeout(async()=>{try{const A=await loadAMap();const auto=new A.AutoComplete({city:'成都',citylimit:true});auto.search(value,(status,result)=>{if(revision!==placeQueryRevision||q('pickup')?.value!==value)return;state.remotePlaces=(status==='complete'?result.tips||[]:[]).filter(p=>p.location&&p.id&&/^[A-Za-z0-9_-]+$/.test(p.id)).slice(0,8).map(p=>({id:'amap-'+p.id,name:p.name,detail:`${p.district||''} ${typeof p.address==='string'?p.address:''}`.trim(),lat:p.location.getLat(),lon:p.location.getLng()}));const current=q('location-panel');if(current&&!current.hidden)current.innerHTML=localizeHTML(regionalLocationOptions(value))})}catch(e){/* Built-in Chengdu results remain available if the provider fails. */}},350)}
async function loadAMap(){
 if(!regionalConfig.amapKey)throw new Error(t('高德地图尚未配置，请先选择成都主要地点。'));
 if(window.AMap)return window.AMap;if(amapPromise)return amapPromise;
 amapPromise=new Promise((resolve,reject)=>{window._AMapSecurityConfig={serviceHost:new URL(regionalConfig.amapServiceHost||'/_AMapService',location.origin).href};let script=document.createElement('script');const timeout=setTimeout(()=>{script.remove();amapPromise=null;reject(new Error(t('高德地图加载超时，请检查网络。')))},15000);script.src='https://webapi.amap.com/maps?v=2.0&key='+encodeURIComponent(regionalConfig.amapKey)+'&plugin=AMap.Geolocation,AMap.AutoComplete,AMap.Geocoder';script.onload=()=>{clearTimeout(timeout);if(window.AMap)resolve(window.AMap);else{amapPromise=null;reject(new Error(t('高德地图未能加载，请检查配置。')))}};script.onerror=()=>{clearTimeout(timeout);amapPromise=null;reject(new Error(t('高德地图未能加载，请检查配置。')))};document.head.append(script)});return amapPromise;
}
async function regionalCurrentLocation(){
 try{toast('正在通过高德获取当前位置…');const A=await loadAMap();const geo=new A.Geolocation({enableHighAccuracy:true,timeout:10000,convert:true,needAddress:true});geo.getCurrentPosition((status,result)=>{if(status!=='complete'||!result.position){toast('未能获取位置，请检查浏览器定位权限或手动选择');return}const longitude=result.position.getLng(),latitude=result.position.getLat();state.locatedCoords={longitude,latitude};const nearest=PLACES.map(p=>({...p,km:kmBetween(latitude,longitude,p.lat,p.lon)})).sort((a,b)=>a.km-b.km)[0];if(nearest.km<=40){state.currentGeo={id:'amap-current',name:result.formattedAddress||'当前定位地点',en:`Current location · ${latitude.toFixed(4)}, ${longitude.toFixed(4)}`,detail:result.formattedAddress||`${latitude.toFixed(5)}, ${longitude.toFixed(5)}`,lat:latitude,lon:longitude};state.selectedLocationId=null;q('pickup').value='';showLocations();toast('已获取当前位置，请选择定位地址或附近地点。')}else{showLocations();toast('已定位，但附近没有列出的成都地点，请手动选择。')}})}catch(e){toast(e.message)}
}
function overviewHTML(){return `<div class="chengdu-overview"><div class="map-caption"><span class="eyebrow">CHENGDU</span><h3>成都主要地点</h3><p class="muted">地点概览示意 · 高德地图待配置</p></div><div class="landmark-grid">${PLACES.map(p=>`<div class="landmark"><span>⌖</span><div><b>${esc(placeLabel(p))}</b><small>${esc(p.detail)}</small></div></div>`).join('')}</div></div>`}
function regionalSearchMapHTML(){return `<div id="search-map" class="regional-map">${regionalConfig.amapKey?'<div class="map-loading">正在加载高德地图…</div>':overviewHTML()}</div><p class="muted map-note">标注为成都主要地点，不代表实际营业门店。地图不提供实时车辆库存。</p>`}
async function mountSearchMap(){if(!regionalConfig.amapKey)return;try{const A=await loadAMap();if(!q('search-map'))return;searchMap=new A.Map('search-map',{zoom:11,center:[104.0665,30.5723],lang:state.lang==='en'?'en':'zh_cn'});const markers=PLACES.map(p=>{const marker=new A.Marker({position:[p.lon,p.lat],title:placeLabel(p)});marker.on('click',()=>{new A.InfoWindow({content:localizeHTML(`<div class="map-info"><b>${esc(placeLabel(p))}</b><p>${esc(p.detail)}</p><small>地点示意</small></div>`)}).open(searchMap,[p.lon,p.lat])});return marker});searchMap.add(markers);searchMap.setFitView(markers)}catch(e){const el=q('search-map');if(el)el.innerHTML=localizeHTML(overviewHTML());toast(e.message)}}
function disposeMaps(){if(searchMap){searchMap.destroy();searchMap=null}}
async function openLocationMap(){hideLocations();const existing=q('location-dialog');if(existing)existing.remove();const dialog=document.createElement('dialog');dialog.id='location-dialog';dialog.setAttribute('aria-label','选择具体地点');dialog.className='location-dialog';dialog.innerHTML=localizeHTML(`<div class="dialog-heading"><div><span class="eyebrow">CHENGDU · AMAP</span><h2>选择具体地点</h2></div><button class="chip" onclick="closeLocationMap()" aria-label="关闭地图">✕</button></div><div id="picker-map" class="picker-map">${regionalConfig.amapKey?'<p class="map-loading">正在加载高德地图…</p>':'<p class="muted">高德地图待配置，可先从以下地点选择。</p>'}</div><div id="picker-selection" class="muted">点击地图标记，再确认选择。</div><div class="picker-list">${PLACES.map(p=>`<button class="chip" onclick="confirmMapPlace('${p.id}')">${esc(placeLabel(p))}</button>`).join('')}</div><p class="map-note muted">地点为取车位置示意，不代表已运营门店。</p>`);document.body.append(dialog);dialog.addEventListener('close',()=>{pickerMap?.destroy();pickerMap=null;dialog.remove();q('pickup')?.focus()});dialog.showModal();if(!regionalConfig.amapKey)return;try{const A=await loadAMap();if(!q('picker-map'))return;pickerMap=new A.Map('picker-map',{center:[104.0665,30.5723],zoom:11,lang:state.lang==='en'?'en':'zh_cn'});const markers=PLACES.map(p=>{const m=new A.Marker({position:[p.lon,p.lat],title:placeLabel(p)});m.on('click',()=>{q('picker-selection').innerHTML=localizeHTML(`<b>${esc(placeLabel(p))}</b><p>${esc(p.detail)}</p><button class="btn" onclick="confirmMapPlace('${p.id}')">确认选择此地点</button>`)});return m});pickerMap.add(markers);pickerMap.setFitView(markers)}catch(e){q('picker-map').innerHTML='<p>'+esc(e.message)+'</p>'}}
function closeLocationMap(){q('location-dialog')?.close()}
function confirmMapPlace(id){regionalChooseLocation(id);closeLocationMap()}
async function accountRequest(path,options={}){if(location.protocol==='file:')throw new Error(t('请通过网站服务打开，才能使用登录注册。'));let response;try{response=await fetch(path,{credentials:'same-origin',signal:AbortSignal.timeout(20000),...options,headers:{'Content-Type':'application/json',...(options.headers||{})}})}catch{throw new Error('网络连接失败或超时。提交结果可能尚未确认，请保留表单后重试。')}let data;try{data=await response.json()}catch{throw new Error(t('账户服务尚未启动，请使用网站启动脚本。'))}if(!response.ok){if(response.status===401&&path==='/api/orders'){state.account=null;state.accountOrders=[]}throw new Error(t(data.error||'操作失败，请稍后重试。'))}return data}
async function bootstrapServices(){if(location.protocol==='file:')return;try{regionalConfig=await accountRequest('/api/config');const me=await accountRequest('/api/auth/me');state.account=me.user;if(state.booking?.accountId&&state.booking.accountId!==state.account?.id){state.booking=null;sessionStorage.removeItem('yichen-booking')}if(state.account){state.favorites=JSON.parse(localStorage.getItem('yichen-favs-'+state.account.id)||'[]');await loadAccountOrders()}render()}catch{/* Static preview remains usable without an account server. */}}
async function loadAccountInquiries(){try{const d=await accountRequest('/api/inquiries');state.accountInquiries=d.inquiries;state.inquiriesError=''}catch{state.accountInquiries=[];state.inquiriesError='需求暂时无法读取，请重试。'}}
async function refreshInquiries(){await loadAccountInquiries();render()}
async function loadAccountOrders(){await loadAccountInquiries();try{const data=await accountRequest('/api/orders');state.accountOrders=data.orders;state.ordersError=''}catch(e){state.accountOrders=[];state.ordersError='历史旅程暂时无法读取，请稍后刷新。'}}
function setAuthMode(mode){state.authMode=mode;state.authError='';render()}
function accountPage(){
 if(state.account)return `<main class="page wrap account-shell"><div class="account-intro"><span class="eyebrow">YOUR YICHEN</span><h1>你好，<span data-i18n-preserve>${esc(state.account.name)}</span>。</h1><p class="muted">账户已登录，可以查看历史旅程并提交用车需求。</p></div><div class="booking-content"><h2>我的账户</h2><p>${esc(state.account.phone||state.account.email)}</p><p class="muted">密码账户 · 本地开发服务</p><div class="hero-actions">${state.account.isOperator?'<a class="btn" href="./operator.html">管理客户需求 ↗</a>':''}<button class="btn" onclick="nav('/trips')">查看我的旅程 ↗</button><button class="btn ghost" onclick="signOut()">退出登录</button></div></div></main>`;
 const register=state.authMode==='register',offline=location.protocol==='file:';
 return `<main class="page wrap account-shell"><div class="account-intro"><span class="eyebrow">YOUR JOURNEY STARTS HERE</span><h1>每段旅程，<br/>都有归处。</h1><p class="muted">注册后可以提交用车需求，登录后查看历史旅程。</p><div class="account-scene"><img src="${DEST[2].image}" alt="四川雪山风景"/><span>CHENGDU → SICHUAN</span></div></div><div class="booking-content auth-card"><div class="tabs"><button class="chip ${register?'':'active'}" onclick="setAuthMode('login')">登录</button><button class="chip ${register?'active':''}" onclick="setAuthMode('register')">注册</button></div><h2>${register?'创建你的账户':'欢迎回来'}</h2><p class="muted">${register?'使用手机号或邮箱与密码注册。':'使用注册时的手机号或邮箱与密码登录。'}</p>${offline?'<div class="auth-notice">当前为离线页面。请运行“启动网站.command”打开账户服务，再进行登录注册。</div>':''}<form onsubmit="submitAccount(event)">${register?'<div class="formfield"><label for="auth-name">称呼</label><input id="auth-name" name="name" required maxlength="50" autocomplete="name" placeholder="怎么称呼你"/></div>':''}<div class="formfield"><label for="auth-email">手机号 / 邮箱</label><input id="auth-email" name="account" type="text" required maxlength="254" autocomplete="username" placeholder="11位手机号或邮箱"/></div><div class="formfield"><label for="auth-password">密码</label><input id="auth-password" name="password" type="password" required minlength="10" maxlength="128" autocomplete="${register?'new-password':'current-password'}" placeholder="至少 10 位字符"/><button type="button" class="password-toggle" onclick="togglePassword('auth-password',this)" aria-pressed="false">显示密码</button></div>${register?'<div class="formfield"><label for="auth-confirm">确认密码</label><input id="auth-confirm" type="password" required minlength="10" autocomplete="new-password" placeholder="再次输入密码"/><button type="button" class="password-toggle" onclick="togglePassword(\'auth-confirm\',this)" aria-pressed="false">显示密码</button></div>':''}<p id="auth-error" class="auth-error" role="alert">${esc(state.authError||'')}</p><button class="btn" id="auth-submit" type="submit" ${offline?'disabled':''}>${register?'创建账户':'登录'} ↗</button></form><p class="muted auth-footnote">此账户服务用于开发体验；租车库存与支付仍为演示。手机号和邮箱尚未验证归属；正式上线前需接入验证码和找回密码服务。</p></div></main>`;
}
async function submitAccount(event){event.preventDefault();const button=q('auth-submit'),register=state.authMode==='register',email=q('auth-email').value.trim(),password=q('auth-password').value;if(button.disabled)return;if(register&&password!==q('auth-confirm').value){q('auth-error').textContent=t('两次输入的密码不一致。');return}button.disabled=true;try{const data=await accountRequest('/api/auth/'+(register?'register':'login'),{method:'POST',body:JSON.stringify({account:email,password,name:register?q('auth-name').value.trim():undefined})});state.account=data.user;state.authError='';state.favorites=JSON.parse(localStorage.getItem('yichen-favs-'+data.user.id)||'[]');await loadAccountOrders();render();toast((register?'注册成功，已登录。':'登录成功。')+(state.ordersError?' '+state.ordersError:''))}catch(e){state.authError=e.message;q('auth-error').textContent=e.message}finally{if(q('auth-submit'))q('auth-submit').disabled=false}}
async function signOut(){try{await accountRequest('/api/auth/logout',{method:'POST',body:'{}'});state.account=null;state.accountOrders=[];state.accountInquiries=[];sessionStorage.removeItem('yichen-enquiry-receipt');state.booking=null;sessionStorage.removeItem('yichen-booking');state.favorites=[];render();toast('已退出登录。')}catch(e){toast(e.message)}}
function inquiryReceiptHTML(v){const labels={pending:'待联系',quoted:'已报价',reserved:'已预约',completed:'已完成',cancelled:'已取消'},c=CARS.find(c=>c.id===v.car);return `<article class="inquiry-receipt"><div class="inquiry-receipt-heading"><h2>${esc(c?.name||'用车需求')}</h2><span>${labels[v.status]||'待联系'}</span></div><p>${esc(v.id)}</p><p>${esc(dateLabel(v.startAt))} — ${esc(dateLabel(v.endAt))} · 估算 ${esc(v.durationDays)} 天</p>${v.pickup?`<p>${esc(v.pickup)} → ${esc(v.returnAt)}</p>`:''}<p class="muted">需求跟进记录。车辆、报价与预约以双方确认的合同为准；这里不表示已付款或已锁车。</p></article>`}
function regionalTrips(){
 const tab=window.tripTab||'即将出发',orders=state.account?(state.accountOrders||[]):state.booking?.order?[state.booking]:[];
 const receipt=storedJSON(sessionStorage,'yichen-enquiry-receipt',null),inquiries=state.account?(state.accountInquiries||[]):receipt?[receipt]:[];
 return `<main class="page wrap" style="min-height:65vh"><div class="subhero"><span class="eyebrow">MY JOURNEYS</span><h1>我的需求与旅程</h1><p>${state.account?'查看已提交需求和跟进状态；历史演示订单单独列示。':'未登录提交的回执仅保留在本标签页，关闭后请凭咨询编号联系经营者。'}</p></div><section aria-label="我的用车需求"><h2>已提交需求</h2>${state.account?'<button class="btn ghost" onclick="refreshInquiries()">刷新需求状态</button>':''}${state.inquiriesError&&state.account?`<p role="alert">${esc(state.inquiriesError)}</p>`:inquiries.length?inquiries.map(inquiryReceiptHTML).join(''):'<div class="empty"><p>暂时没有提交的需求。</p><a class="btn" href="#/search">选择座驾</a></div>'}</section><section aria-label="历史演示旅程"><h2>历史演示旅程</h2><p class="muted">以下演示记录不代表真实预约或付款。</p><div class="tabs">${['即将出发','正在进行','历史旅程'].map(x=>`<button class="chip ${tab===x?'active':''}" onclick="window.tripTab='${x}';render()">${x}</button>`).join('')}</div>${state.ordersError?`<p role="alert">${esc(state.ordersError)}</p>`:''}${tab==='即将出发'&&orders.length?orders.map(b=>{const c=CARS.find(x=>x.id===b.car)||CARS[1];return `<article class="trip-card" style="margin-bottom:20px"><img src="${c.image}" alt="${c.name}"/><div><span class="eyebrow">演示订单 · ${esc(b.order)}</span><h2 style="font-size:2rem;margin:9px 0">${c.name}</h2><p class="muted">${esc(b.pickup)}<br/>${esc(dateLabel(b.start))} — ${esc(dateLabel(b.end))}</p><button class="btn ghost" onclick="viewSavedTrip('${esc(b.order)}')">查看行程详情 ↗</button></div></article>`}).join(''):'<p class="muted">暂无对应的历史演示记录。</p>'}</section></main>`;
}
function viewSavedTrip(id){const b=(state.accountOrders||[state.booking]).find(x=>x?.order===id);if(b){state.booking=b;state.protection=b.protection||'基础保障';state.extras=b.extras||[];save();nav('/success')}}

function togglePassword(id,button){const input=document.getElementById(id);if(!input)return;const visible=input.type==='password';input.type=visible?'text':'password';button.textContent=t(visible?'隐藏密码':'显示密码');button.setAttribute('aria-pressed',String(visible))}
